mixed-template-choice.specification:
yamaa: "1.0"
type: spec
domain: TEST
base: SRC
keys: [ID, KIND, CUT]
input:
  SRC: {path: src.csv, types: {CUT: int}}
  DONOR: {path: donor.csv, types: {SEQ: int, CUT: int, X: int}}
output: {path: result.csv, columns: [ID, KIND, CUT, VALUE]}
intermediates:
  - id: P
    dataset: DONOR
    key: {ID: ID, CUT: CUT, MODE: KIND}
    order_by: [DONOR.SEQ]
    keep: first
columns:
  - {name: ID, type: str, derivation: SRC.ID}
  - {name: KIND, type: str}
  - {name: CUT, type: int, derivation: SRC.CUT}
  - {name: VALUE, type: int, derivation: P.X}
rows:
  - {id: grouped, dataset: SRC, group_by: [SRC.ID, SRC.CUT], derivations: {KIND: "'group'"}}
  - {id: records, dataset: SRC, derivations: {KIND: "'record'"}}
verifications:
  - assert: {id: selected, when: "P.X > 0", require: "P.X = VALUE"}
  - row_count: {min: 4, max: 4}

prior-failure-before-require-name.specification:
yamaa: "1.0"
type: spec
domain: TEST
base: SRC
keys: [ID]
input:
  SRC: src.csv
  DONOR: {path: donor.csv, types: {SEQ: int, X: int}}
output: {path: result.csv, columns: [ID, VALUE]}
intermediates:
  - id: P
    dataset: DONOR
    key: [ID]
    order_by: [DONOR.SEQ]
    keep: first
columns:
  - {name: ID, type: str, derivation: SRC.ID}
  - {name: VALUE, type: int, derivation: 2}
verifications:
  - unique: {columns: [VALUE], id: prefix}
  - assert: {id: selected, when: "P.X > 0", require: "UNKNOWN > 0"}
  - row_count: {min: 3, max: 3}

